#!/usr/bin/env node
'use strict';

// Privat modellkontroll. Ingen skjerm-, app-, tilgangs- eller databasebevis.
// Vert leser modell og valgfri oppdiktet medlemsfixture; VM får bare kildetekst.
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const crypto = require('node:crypto');

const args = process.argv.slice(2);
const exportArg = args[0];
const outIndex = args.indexOf('--out');
if (!exportArg || args.some((v, i) => i > 0 && i !== outIndex && i !== outIndex + 1) || (outIndex >= 0 && !args[outIndex + 1])) {
  console.error('Bruk: node precision-wb-model-check.cjs <eksportrot> [--out <privat-bevis.json>]');
  process.exit(2);
}

const privateBase = fs.realpathSync(path.join(require('node:os').homedir(), 'Documents/Claude/akgolf-hq'));
const inside = (base, target) => { const r = path.relative(base, target); return r !== '..' && !r.startsWith('..' + path.sep) && !path.isAbsolute(r); };
let exportRoot, modelPath, source, membershipFixturePath, membershipFixtureSource;
try {
  exportRoot = fs.realpathSync(exportArg);
  modelPath = fs.realpathSync(path.join(exportRoot, 'ui_kits/_shared/wb-model.js'));
  if (!inside(exportRoot, modelPath)) throw new Error('Modellfilen ligger utenfor oppgitt eksportrot');
  source = fs.readFileSync(modelPath, 'utf8');
  // Bare gruppeprøver laster denne faktiske, oppdiktede medlemsdatakilden i VM.
  const fixture = path.join(exportRoot, 'ui_kits/_shared/data-wb3.js');
  if (fs.existsSync(fixture)) {
    membershipFixturePath = fs.realpathSync(fixture);
    if (!inside(exportRoot, membershipFixturePath)) throw new Error('Medlemsfixture ligger utenfor eksportroten');
    membershipFixtureSource = fs.readFileSync(membershipFixturePath, 'utf8');
  }
} catch (e) {
  console.error(JSON.stringify({ status: 'ERROR', stage: 'root-attestering', error: e.message }));
  process.exit(2);
}

const setup = String.raw`
  globalThis.window = globalThis;
  globalThis.location = { pathname: '/agencyos/synthetic.html', search: '?ns=synthetic-model-check&lagre=1' };
  // Kun de nettleserstandardene modellen bruker. Alle objekter/funksjoner lages i VM.
  globalThis.URLSearchParams = class {
    constructor(query='') { this.parts=String(query).replace(/^\?/, '').split('&').filter(Boolean).map(pair=>{const i=pair.indexOf('=');return [i<0?pair:pair.slice(0,i),i<0?'':pair.slice(i+1)].map(v=>decodeURIComponent(v.replace(/\+/g,' ')));}); }
    get(name) { const pair=this.parts.find(p=>p[0]===String(name));return pair?pair[1]:null; }
  };
  const storageData=new Map();
  globalThis.localStorage={
    get length(){return storageData.size;},
    key(i){return Array.from(storageData.keys())[Number(i)] ?? null;},
    getItem(k){if(globalThis.TEST_STORAGE_READFAIL)throw Error('Syntetisk lesefeil');return storageData.has(String(k))?storageData.get(String(k)):null;},
    setItem(k,v){const point=globalThis.TEST_STORAGE_FAILONCOUNT;if(point && point.key===String(k)){point.seen++;if(point.seen===point.n)throw Error('Syntetisk lagringsfeil på valgt skriving');}if(globalThis.TEST_STORAGE_FAIL || globalThis.TEST_STORAGE_FAILKEY===String(k))throw Error('Syntetisk lagringsfeil');storageData.set(String(k),String(v));},
    removeItem(k){storageData.delete(String(k));},clear(){storageData.clear();}
  };
  window.WB3 = {
    bank: [{id:'b1',name:'Syntetisk øvelse A',area:'Teknikk',axis:'tek',min:10},
           {id:'b2',name:'Syntetisk øvelse B',area:'Fysisk',axis:'fys',min:20}],
    fysProg: [], turn: [], yr: {eventPool:[]}
  };
  const assert = (value, message) => { if (!value) throw Error('CONTROL_ASSERTION:' + message); };
  const need = (...names) => { for (const name of names) if (typeof window.WB[name] !== 'function') throw Error('API_UKJENT:' + name); };
  const success = r => { assert(r && r.ok === true, 'Forutsetning feilet'); return r; };
  const WB = () => window.WB;
  const plan = () => success(WB().createPlan({owner:'spiller:synthetic-owner',navn:'Syntetisk plan',fra:'2026-10-01',til:'2026-12-31',mal:'tom'})).plan;
  const session = (p, patch={}) => success(WB().saveSession(p.id,{navn:'Syntetisk økt',dato:'2026-11-05',startTid:'',minutter:'',dominerende:'tek',draftId:'synthetic-draft',...patch})).session;
  const entry = p => success(WB().addEntry(p.id,{navn:'Syntetisk turnering',fra:'2026-11-05',til:'2026-11-08',bane:'Syntetisk bane'},'synthetic-entry')).entry;
  const round = (p,e,patch={}) => success(WB().addRound(p.id,e.tournamentEntryId,{dato:'2026-11-06',startTid:'10:00',hull:'18',...patch},'synthetic-round')).round;
  const roundSession = (p,e,r,key='synthetic-round-plan') => success(WB().planRounds(p.id,e.tournamentEntryId,[{roundId:r.roundId,startTid:'10:00',minutter:''}],key));
  const state = p => JSON.stringify(p);
  const rejectedUnchanged = (p, call) => { const before=state(p),r=call();assert(r && r.ok === false,'Ugyldig handling ble godtatt');assert(state(p)===before,'Avvist handling endret plan/økt/forespørsel'); };
  const task = (patch={}) => ({technicalPlanId:'synthetic-tp',taskId:'synthetic-task',rev:1,sourceOwnerId:'synthetic-owner',pos:'P7',title:'Syntetisk oppgave',area:'Teknikk',sourceTaskRev:1,snapshot:{task:{id:'synthetic-task',rev:1,title:'Syntetisk oppgave'},media:{for:{navn:'synthetic.jpg'}}},...patch});
  const tekScope = () => { window.TP2={scope:()=>({playerId:'synthetic-owner',planId:'synthetic-tp'})}; };
  const countFields = (patch={}) => ({ownerType:'spiller',ownerId:'synthetic-owner',technicalPlanId:'synthetic-tp',antall:'2',gyldigFra:'2026-10-01',gyldigTil:'2026-12-31',...patch});
  const countSource = (p,patch={},req='synthetic-count') => success(WB().setTeknikkAntall(p.id,countFields(patch),req)).kilde;
  const tekPeriod = p => success(WB().addPeriod(p.id,{type:'Grunnperiode',fra:p.fra,til:p.til,budsjett:{fys:4,tek:7,slag:5,spill:0,turn:1},minutter:{fys:45,tek:null,slag:60,spill:0,turn:90}})).period;
  const countImport = (per,c,patch={}) => ({scope:'periode',key:per.id,planningCountId:c.planningCountId,rev:c.rev,ownerId:c.ownerId,technicalPlanId:c.technicalPlanId,...patch});
  const newTechFields = (patch={}) => ({ownerType:'spiller',ownerId:'synthetic-owner',navn:'Syntetisk teknisk plan',gyldigFra:'2026-10-01',gyldigTil:'2026-12-31',...patch});
  const newTechPlan = (patch={},req='synthetic-new-tp') => success(WB().createTechPlan(newTechFields(patch),req)).plan;
  const groupYear = () => success(WB().createPlan({owner:'gruppe:synthetic-group',navn:'Syntetisk gruppeplan',fra:'2026-10-01',til:'2026-12-31',mal:'tom'})).plan;
  const groupCount = (p,tp,antall='2',req='synthetic-group-count') => success(WB().setTeknikkAntall(p.id,countFields({ownerType:'gruppe',ownerId:'synthetic-group',technicalPlanId:tp.technicalPlanId,antall}),req)).kilde;
  const technicalRevision = (rev,patch={}) => {
    const body={id:'synthetic-task',rev,pos:'P7',title:'Syntetisk revisjon '+rev,area:'Teknikk',focus:'synthetic-focus',club:'7i',veiledendeReps:10,step:1,env:1,press:1,gear:'synthetic-gear',src:'synthetic-source',...patch};
    return task({...body,sourceTaskRev:rev,tittel:body.title,snapshot:{task:body,media:{for:{navn:'synthetic-revision-'+rev+'.jpg'}}}});
  };
`;

