  const sourceBefore=state(WB().planById(g.id)),own=success(WB().createOwnVersion(g.id,gs.id,'synthetic-owner',personal.id,'own-full-request')),cp=WB().planById(own.planId),cs=cp.oekter.find(x=>x.id===own.sessionId);
