// Publiseringsprotokoll: én utkastskriving må gi konsistent suksess.
// Hvis andre skriving finnes, må injisert feil tilbakeføre alle lagre.
for (const baseId of [
  'task-publication-draft-write-failure-rolls-back-shared-store-too',
  'count-publication-draft-write-failure-rolls-back-shared-store-too'
]) {
  const original = cases.find(c => c[0] === baseId);
  let secondWriteBody = original[2]
    .replace('globalThis.TEST_STORAGE_FAILKEY=draftKey;', 'const failpoint={key:draftKey,n:2,seen:0};globalThis.TEST_STORAGE_FAILONCOUNT=failpoint;')
    .replace('globalThis.TEST_STORAGE_FAILKEY=null;', "globalThis.TEST_STORAGE_FAILONCOUNT=null;assert((failpoint.seen===1 && r.ok===true) || (failpoint.seen===2 && r.ok===false),'Publiseringsprotokoll: forventet én skriving + suksess eller andre skrivefeil + avvisning');");
  if (secondWriteBody === original[2] || secondWriteBody.includes('TEST_STORAGE_FAILKEY')) throw Error('Kontrolladapter for andre skriving mangler');
  const prefix = secondWriteBody.split('assert(r.ok===false')[0];
  const isTask = baseId.startsWith('task-');
  const localExpr = isTask ? 'JSON.stringify(WB().techPlanRaw(tp.technicalPlanId))===before' : 'JSON.stringify(WB().tekKilder(src))===before';
  const committedCheck = isTask
    ? `(()=>{const loc=WB().techPlanRaw(tp.technicalPlanId),lt=loc.tasks.find(x=>x.taskId===t.taskId),dt=JSON.parse(localStorage.getItem(draftKey)).S.tp[tp.technicalPlanId],sh=JSON.parse(localStorage.getItem(sharedKey)).plans[tp.technicalPlanId].tasks[t.taskId];return JSON.stringify(loc)===JSON.stringify(dt) && lt.publisert.publishedRev===2 && JSON.stringify(lt.publisert)===JSON.stringify(sh);})()`
    : `(()=>{const loc=WB().tekKilder(src).find(x=>x.planningCountId===c.planningCountId),dt=Object.values(JSON.parse(localStorage.getItem(draftKey)).S.tek).flat().find(x=>x.planningCountId===c.planningCountId),sh=JSON.parse(localStorage.getItem(sharedKey)).tek[c.planningCountId];return JSON.stringify(loc)===JSON.stringify(dt) && loc.publisert.rev===2 && loc.publisert.antall===3 && sh.rev===2 && sh.antall===3 && sh.ownerId===loc.ownerId && sh.technicalPlanId===loc.technicalPlanId;})()`;
  const phCheck = isTask
    ? `WB().techPlan(tp.technicalPlanId).tasks[0].title===(singleWrite?'Syntetisk ny publisering':'Syntetisk publisert gammel')`
    : `(()=>{const x=WB().tekKilder(src).find(x=>x.planningCountId===c.planningCountId),v=x && (x.publisert || x);return !!v && v.antall===(singleWrite?3:2) && v.rev===(singleWrite?2:1);})()`;
  secondWriteBody = [
    prefix + `const singleWrite=failpoint.seen===1,facts=singleWrite?{oneWrite:failpoint.seen===1,accepted:r.ok===true,localChanged:!(${localExpr}),draftChanged:localStorage.getItem(draftKey)!==draft,sharedChanged:localStorage.getItem(sharedKey)!==shared,committedConsistent:${committedCheck}}:{twoWrites:failpoint.seen===2,rejected:r.ok===false,localUnchanged:${localExpr},draftUnchanged:localStorage.getItem(draftKey)===draft,sharedUnchanged:localStorage.getItem(sharedKey)===shared};location.pathname='/playerhq/synthetic.html';`,
    {reloadModel:true},
    `assert(WB().role()==='spiller','PH-pathname aktiverte ikke spillerrollen');facts.phReloadConsistent=${phCheck};assert(Object.values(facts).every(x=>x===true),'Publiseringsprotokoll: forventet alle true, faktisk '+JSON.stringify(facts));`
  ];

  cases.push([baseId.replace('draft-write-failure', 'second-draft-write-failure'), original[1], secondWriteBody]);
}

